import { approvedReportPath } from './report-link.mjs';
export function escapeHTML(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}
export function money(value) {
  return Number.isSafeInteger(value) && value >= 0 ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value / 100) : 'Not reconciled';
}
export function parsePrice(value) {
  if (typeof value !== 'string' || !/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(value)) return null;
  const [whole, fractional = ''] = value.split('.');
  const result = BigInt(whole) * 100n + BigInt(fractional.padEnd(2, '0'));
  return result > 0n && result <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(result) : null;
}
function list(value) { return Array.isArray(value) ? value : Object.values(value ?? {}); }
function localUrl(value, localDemo, evidencePrefix='/api/marketplace/evidence/') {
  const prefix=localDemo?'/demo/':evidencePrefix;
  return typeof value === 'string' && /^\/[A-Za-z0-9_-]+(?:\/[A-Za-z0-9_-]+)*\/$/.test(prefix) && value.startsWith(prefix) && /^\/[a-zA-Z0-9_./?-]+$/.test(value) && !value.includes('..') ? value : '';
}
const h = escapeHTML;
const amountRow = (label, value, className = '') => `<div class="amount-row ${className}"><dt>${h(label)}</dt><dd>${h(money(value))}</dd></div>`;
const button = (action, label, attrs = '', disabled = false, secondary = false) => `<button type="button" class="${secondary ? 'button secondary' : 'button'}" data-action="${action}" ${attrs}${disabled ? ' disabled' : ''}>${h(label)}</button>`;
const identifier = (name, value) => `data-${name}="${h(value)}"`;

export function renderApp(data, ui = {}) {
  const localDemo = data?.mode === 'SYNTHETIC_LOCAL' && data?.runtime !== 'AUTHENTICATED';
  const authenticated = data?.schema === 'atlas-marketplace-workspace-v1' && ['SYNTHETIC_LOCAL', 'PROVIDER_SANDBOX', 'PRODUCTION'].includes(data.environment) && ['BUYER', 'SELLER', 'STAFF'].includes(data.scope?.role);
  if (!localDemo && !authenticated) return `<main class="loading"><p class="eyebrow">ATLAS / LOCAL PILOT</p><h1>Marketplace unavailable</h1><p>Sign-in or the required marketplace service is unavailable. Refresh saved state to check access.</p>${button('refresh', 'Refresh saved state')}</main>`;
  const listings = list(data.listings);
  const reservations = list(data.reservations);
  const orders = list(data.orders);
  const intents = list(data.intents);
  const cards = list(data.eligibilityCards);
  const selected = listings.find((item) => item.id === ui.selectedListingId) ?? listings.find((item) => item.status === 'ACTIVE') ?? listings[0];
  const card = selected?.approvedCard ?? cards[0];
  const identity = card?.identity;
  const now = Number.isSafeInteger(ui.now) ? ui.now : Number.isSafeInteger(data.now) ? data.now : Date.now();
  const quote = ui.quote?.listingHash === selected?.bindingHash ? ui.quote : null;
  const role = localDemo ? 'LOCAL_DEMO' : data.scope.role;
  const can = kind => role === 'LOCAL_DEMO' || role === kind;
  const activeCommerce = selected && ['ACTIVE', 'RESERVED', 'SOLD'].includes(selected.status);
  const editable = selected?.status === 'ACTIVE' && can('SELLER');
  const policy = selected?.policy ?? data.policy;
  const consent = card ? data.consent?.[card.cardId] : null;
  const reserved = reservations.find((item) => item.listingId === selected?.id && ['HELD', 'PAYMENT_PENDING', 'SOLD'].includes(item.status));
  const payment = intents.find((item) => item.id === reserved?.paymentIntentId);
  const blocked = Boolean(ui.busy || ui.uncertain);
  const firstName = identity?.name ?? (localDemo ? 'No synthetic specimen available' : 'No eligible approved card available');
  const side = ui.side === 'back' ? 'back' : 'front';
  const src = localUrl(card?.media?.[side]?.url, localDemo, ui.evidencePathPrefix);
  const report = approvedReportPath(card?.reportUrl,card?.reportVersion)??localUrl(card?.reportUrl, localDemo, ui.evidencePathPrefix);
  const controlAttrs = reserved ? identifier('reservation', reserved.id) : '';
  return `
    <div class="local-banner"><span class="local-dot" aria-hidden="true"></span><strong>${localDemo ? 'LOCAL SYNTHETIC DEMO' : data.environment === 'PROVIDER_SANDBOX' ? 'PROVIDER SANDBOX' : 'ATLAS MARKETPLACE'}</strong><span>${localDemo ? 'No real cards, payments or shipments.' : data.environment === 'PROVIDER_SANDBOX' ? 'Authenticated workspace · Test money only.' : `Authenticated ${h(role.toLowerCase())} workspace`}</span></div>
    <header class="site-header"><a href="#main" class="wordmark" aria-label="ATLAS marketplace home">ATLAS<span>MARKETPLACE</span></a><nav aria-label="Marketplace"><a href="#browse">Browse</a>${can('SELLER') ? '<a href="#sell">Sell a card</a>' : ''}${can('BUYER') && data.destinationsEnabled ? '<a href="#delivery-addresses">Delivery addresses</a>' : ''}<a href="#orders">Orders</a>${can('SELLER') ? '<a href="#balance">ATLAS Balance</a>' : ''}<a href="#protection">Protection</a>${role === 'STAFF' && data.taxReporting ? '<a href="#tax-reporting">Tax reporting</a>' : ''}</nav><span class="pilot-label">${localDemo ? 'R2 / LOCAL PILOT' : h(role)}</span></header>
    <main id="main">
      <div class="page-heading"><div><p class="eyebrow">${localDemo ? 'THE ATLAS-HELD PILOT' : 'ATLAS-HELD MARKETPLACE'}</p><h1>Every card. Every detail.</h1><p>Review the card, the terms, and the complete path to payment.</p></div>${button('refresh', 'Refresh saved state', '', Boolean(ui.busy), true)}</div>
      <div class="notice ${ui.uncertain ? 'attention' : ''}" role="status" aria-live="polite">${h(ui.notice ?? (localDemo ? 'This isolated preview uses only synthetic evidence and a local payment simulator. Commercial policy and real seller authority remain unapproved.' : 'Your authenticated workspace shows only permitted orders and retained evidence. Unavailable evidence never authorizes a new action.'))}${ui.uncertain ? '<p>The last response is unknown. Refresh saved state before taking another action. A payment retry will never be dispatched automatically.</p>' : ''}</div>
      ${role==='BUYER'&&data.destinationsEnabled?renderDestinations(data.quoteDestinations??[],ui,blocked):''}
      <section id="browse" class="catalog-search" aria-labelledby="catalog-heading"><h2 id="catalog-heading">Available listings</h2><p class="small">These filters search listed inventory. A collection display is not a listing.</p>${renderCatalogFilters(ui.catalogFilters ?? {}, blocked)}${ui.catalog ? `<p class="small">${h(ui.catalog.total)} matching available listing${ui.catalog.total === 1 ? '' : 's'}.</p>${ui.catalog.items?.length ? `<div class="catalog-results">${ui.catalog.items.map((item) => button('select-listing', `${item.approvedCard.identity.name} · ${money(item.askingPriceCents)}`, identifier('listing', item.id), false, true)).join('')}</div>` : '<p class="empty-state">No available listings match these filters.</p>'}` : ''}</section>
      <section class="product-layout" aria-labelledby="specimen-heading" ${ui.catalog?.total === 0 ? 'hidden' : ''}>
        <div class="media-column"><div class="media-stage">${src ? `<img class="specimen" src="${h(src)}" width="600" height="900" alt="${h(side === 'front' ? 'Front' : 'Back')} ${localDemo ? 'of the explicitly synthetic local specimen' : 'from the exact approved card evidence'}">` : `<p class="empty-media">${localDemo ? 'Exact media unavailable' : 'Qualified approved media is unavailable. No placeholder card image is substituted.'}</p>`}</div><div class="media-controls" role="group" aria-label="Card photograph side">${button('side', 'Front', 'data-side="front" aria-pressed="' + (side === 'front') + '"', false, true)}${button('side', 'Back', 'data-side="back" aria-pressed="' + (side === 'back') + '"', false, true)}${report ? `<a class="report-link" href="${h(report)}" target="_blank" rel="noopener">▤ Grade Report <span class="sr-only">${localDemo ? '(synthetic; opens a new tab)' : '(opens a new tab)'}</span><span aria-hidden="true">↗</span></a>` : ''}</div><p class="image-caption">${localDemo ? 'Synthetic artwork · Exact saved Front, Back and report revision.' : 'Exact approved evidence only. Media availability is separate from title and listing eligibility.'}</p></div>
        <div class="purchase-column"><p class="eyebrow">${h(identity?.category ?? (localDemo ? 'SYNTHETIC SPECIMEN' : 'APPROVED CARD EVIDENCE'))} / ${h(identity?.year ?? 'YEAR UNKNOWN')}</p><h2 id="specimen-heading">${h(firstName)}</h2><p class="set-name">${h(identity?.set ?? 'Set not recorded')}</p><dl class="facts"><div><dt>Certificate</dt><dd>${h(card?.certificateId ?? 'Unavailable')}</dd></div><div><dt>Report</dt><dd>${card ? `Version ${h(card.reportVersion)}` : 'Unavailable'}</dd></div><div><dt>Fulfillment</dt><dd>ATLAS-held${localDemo ? ' · synthetic' : ''}</dd></div><div><dt>Seller</dt><dd>${localDemo ? 'Synthetic seller' : 'Authenticated marketplace listing'}</dd></div></dl>
        <div class="price-block"><span class="eyebrow">${selected ? 'ASKING PRICE' : 'PREPARE A LISTING BELOW'}</span><p class="asking-price">${selected ? h(money(selected.askingPriceCents)) : 'Not listed'}</p><span class="status-pill">${h(selected?.status === 'ACTIVE' ? 'Available listing' : selected?.status === 'RESERVED' ? 'Reserved for checkout' : selected?.status === 'SOLD' ? (localDemo ? 'Synthetic sale recorded' : 'Sale recorded') : 'Collection specimen · not for sale')}</span></div>
        ${can('BUYER') ? renderCheckout(selected, quote, reserved, payment, blocked, now, localDemo, data, ui) : ''}
        ${policy ? `<details class="policy-details"><summary>Protection, returns and seller terms</summary><p>${h(policy.protectionTerms)}</p><p>${h(policy.returnsTerms)}</p><p>${h(policy.transferReleaseTerms)}</p><p>${h(policy.payoutTerms)}</p><p class="small">Policy ${h(policy.id)} / ${h(policy.version)}. ${localDemo ? 'Demonstration terms only.' : 'Terms retained with this listing.'}</p></details>` : ''}</div>
      </section>
      ${can('SELLER') ? renderSeller({ card, firstName, selected, editable, activeCommerce, consent, policy, blocked, ui, localDemo, feePreviewRequired: data.feePreviewRequired === true, now }) : ''}
      <section class="workflow-section" id="orders" aria-labelledby="orders-heading"><div class="section-heading"><p class="eyebrow">02 / FULFILLMENT</p><h2 id="orders-heading">From payment to delivery.</h2><p>Progress requires a recorded event. Elapsed time never proves packing, dispatch or delivery.</p></div>${orders.length ? orders.map((order) => renderOrder(order, data.fulfillment?.[order.orderId], intents, blocked, can, localDemo,data.destinationsEnabled,ui.deliveryAddresses?.[order.orderId])).join('') : `<div class="empty-state"><span aria-hidden="true">↗</span><h3>No paid orders yet.</h3><p>A confirmed ${localDemo ? 'synthetic ' : ''}payment will appear here with its exact card, report and total.</p></div>`}</section>
      ${can('SELLER') ? `<section class="workflow-section" id="balance" aria-labelledby="balance-heading"><div class="section-heading"><p class="eyebrow">03 / SELLER PROCEEDS</p><h2 id="balance-heading">ATLAS Balance</h2><p>${localDemo ? 'Sale proceeds in USD. This demo has no real funds, bank account or Ten Kings TKD connection.' : 'USD sale proceeds. Pending, available, restricted and bank-paid amounts reflect their separate recorded operations.'}</p></div>${renderBalance(data.balance, intents, blocked, data.sellerEligibility, localDemo, ui, now)}</section>` : ''}
      ${renderProtection(orders, data.fulfillment ?? {}, intents, blocked, can, localDemo)}
      ${role === 'STAFF' ? renderFinanceIncidents(data.operations, blocked) : ''}
      ${role === 'STAFF' && !localDemo ? renderTaxReporting(data.taxReporting, blocked) : ''}
      <footer><span class="wordmark small-wordmark">ATLAS</span><p>${localDemo ? 'R2 local qualification · Real authority and production routes remain disabled.<br>Physical packaging, coverage, legal policy and provider sandbox acceptance remain separate.' : 'Authenticated ATLAS marketplace workspace.<br>Ownership claims and customer ownership history remain disabled.'}</p></footer>
    </main>`;
}

function sellerNet(price, fee) {
  const value = parsePrice(price);
  return value !== null && Number.isSafeInteger(fee) && value > fee ? value - fee : null;
}

function renderDestinations(destinations,ui,blocked){
  const edit=ui.editDestination;
  const input=(name,label,autocomplete,max)=>`<label>${label}<input name="${name}" autocomplete="${autocomplete}" maxlength="${max}" ${name==='line2'?'':'required'} ${blocked?'disabled':''}></label>`;
  return `<section class="workflow-section" id="delivery-addresses"><div class="section-heading"><h2>Delivery addresses</h2><p>Choose a saved address for shipping and tax. Changing an address requires a new checkout quote; a paid order keeps its original delivery address.</p></div>${destinations.map(row=>`<div class="panel"><strong>${h(row.label)}</strong><div class="inline-actions">${button('edit-destination','Replace saved address',identifier('destination',row.id),blocked,true)}${button('remove-destination','Remove saved address',identifier('destination',row.id),blocked,true)}</div></div>`).join('')}<form data-form="destination" class="panel destination-form"><h3>${edit?'Replace '+h(edit.label):'Add a delivery address'}</h3><label>Address label<input name="label" value="${h(edit?.label??'')}" maxlength="100" required ${blocked?'disabled':''}></label>${input('name','Recipient name','shipping name',100)}${input('phone','Phone including country code (for example +15551234567)','shipping tel',16)}${input('line1','Street address','shipping address-line1',200)}${input('line2','Apartment or suite (optional)','shipping address-line2',200)}${input('city','City','shipping address-level2',100)}${input('state','State (two letters)','shipping address-level1',2)}${input('postalCode','ZIP code','shipping postal-code',10)}<p>United States</p><label>Address type<select name="residential" ${blocked?'disabled':''}><option value="unknown">Not sure</option><option value="yes">Residential</option><option value="no">Business</option></select></label><button class="button" type="submit" ${blocked?'disabled':''}>${edit?'Replace address':'Save address'}</button>${edit?button('new-destination','Cancel replacement','',blocked,true):''}</form></section>`;
}
function renderOrder(order, fulfillment, intents, blocked, can, localDemo,destinationsEnabled,address) {
  const status = fulfillment?.status ?? order.status;
  const next = { AWAITING_PACKING: ['PACK', 'Record synthetic packing evidence'], PAID: ['PACK', 'Record synthetic packing evidence'], PACKED: ['DISPATCH', 'Record synthetic tracked dispatch'], DISPATCHED: ['DELIVER', 'Record synthetic delivery evidence'], DELIVERED: ['RELEASE', 'Release synthetic seller proceeds'] }[status];
  const transfers = intents.filter((item) => item.kind === 'TRANSFER' && item.orderId === order.orderId);
  return `<article class="order-panel"><div><p class="eyebrow">${h(order.orderId)}</p><h3>${h(order.approvedCard?.identity?.name ?? 'Synthetic card order')}</h3><p>${h(money(order.totalCents))} total · ${h(order.approvedCard?.certificateId ?? order.cardId)}</p><span class="status-pill">${h(status ?? 'State unavailable')}</span>${can('STAFF')&&!localDemo&&destinationsEnabled?`${button('delivery-address','View retained delivery address',identifier('order',order.orderId),blocked,true)}${address?`<address>${[address.name,address.line1,address.line2,[address.city,address.state,address.postalCode].join(' '),address.country,address.phone].filter(Boolean).map(h).join('<br>')}</address>`:''}`:''}</div><div class="order-actions"><p class="small">${localDemo ? 'Local test controls record synthetic evidence only.' : 'Record existing evidence for this exact order before advancing a physical milestone.'}</p>${next && can('STAFF') ? localDemo ? button('fulfillment', next[1], `${identifier('order', order.orderId)} data-step="${next[0]}"`, blocked || fulfillment?.cases?.some(item => item.status !== 'CLOSED'), true) : renderFulfillmentForm(order, next[0], blocked || fulfillment?.cases?.some(item => item.status !== 'CLOSED')) : ''}${can('STAFF')&&order.shippingPricing?`<dl class="amounts">${amountRow('Quoted carrier cost',order.shippingPricing.quotedCarrierCostCents)}${amountRow('ATLAS handling charge',order.shippingPricing.handlingCents)}${amountRow('Buyer shipping & handling',order.shippingPricing.buyerChargeCents)}</dl><p class="small">Carrier cost is quoted, not settled. The handling charge is before packaging and labor costs.</p>`:''}${status === 'RELEASED' && can('STAFF') ? button('reconcile-transfer', 'Resume or reconcile original seller transfer', identifier('order', order.orderId), blocked, true) : ''}${transfers.map((intent) => `<p class="small">Seller transfer: ${h(intent.status)}</p>${localDemo && can('STAFF') && ['PENDING', 'UNKNOWN', 'DISPATCHING'].includes(intent.status) ? button('simulate', 'Simulate transfer settlement', `${identifier('intent', intent.id)} data-status="succeeded"`, blocked, true) : ''}`).join('')}</div></article>`;
}

function renderBalance(balance, intents, blocked, eligibility, localDemo, ui, now) {
  const labels = [['Pending', 'pendingCents'], ['Available', 'availableCents'], ['Reserved', 'reservedCents'], ['Withdrawal processing', 'withdrawingCents'], ['Paid out', 'paidOutCents'], ['Recovery due', 'recoveryDueCents']];
  const available = balance?.availableCents;
  const bankReady = eligibility?.status === 'ELIGIBLE' && eligibility.payoutsEnabled === true && (eligibility.bank?.status === 'PAYOUT_READY' || localDemo && eligibility.bank?.status === 'VERIFIED');
  return `${renderSellerEligibility(eligibility, localDemo)}${!localDemo ? button('onboard', 'Review connected account and bank setup with Stripe', '', blocked, true) : ''}<div class="balance-grid">${labels.map(([label, key]) => `<div class="balance-cell"><span>${h(label)}</span><strong>${h(money(balance?.[key]))}</strong></div>`).join('')}</div><div class="withdrawal-row"><div><h3>Cash out to your payout bank</h3><p class="small">Transfer to a connected account and bank payout are separate reconciled operations. No payout date is invented.</p></div>${button('withdraw', localDemo ? 'Withdraw available synthetic proceeds' : 'Withdraw available proceeds', `${identifier('amount', available ?? '')} ${identifier('bank', eligibility?.bank?.externalAccountId ?? '')}`, blocked || !bankReady || (!localDemo && !eligibility?.bank?.externalAccountId) || !Number.isSafeInteger(available) || available <= 0)}</div>${!localDemo && eligibility?.instantPayouts?.available === true ? renderInstantWithdrawal(balance, eligibility, ui, blocked || !bankReady, now) : ''}${intents.filter((item) => item.kind === 'PAYOUT').map((intent) => `<div class="payout-row"><p><strong>${h(money(intent.amountCents))}</strong> · ${h(intent.status)}</p><div class="inline-actions">${button('reconcile-withdrawal', 'Reconcile original withdrawal', identifier('intent', intent.id), blocked, true)}${intent.status === 'PREPARED' ? button('cancel-withdrawal', 'Cancel this undispatched withdrawal', identifier('intent', intent.id), blocked, true) : ''}${localDemo && ['PREPARED', 'PENDING', 'UNKNOWN', 'DISPATCHING'].includes(intent.status) ? button('simulate', 'Simulate bank confirmation', `${identifier('intent', intent.id)} data-status="paid"`, blocked, true) : ''}</div></div>`).join('')}`;
}

function renderCatalogFilters(values, blocked) {
  const field = (name, label, placeholder = '', inputmode = 'text') => `<label>${h(label)}<input name="${name}" inputmode="${inputmode}" value="${h(values[name] ?? '')}" placeholder="${h(placeholder)}" ${blocked ? 'disabled' : ''}></label>`;
  const select = (name, label, options) => `<label>${h(label)}<select name="${name}" ${blocked ? 'disabled' : ''}>${options.map(([value, title]) => `<option value="${h(value)}" ${String(values[name] ?? '') === String(value) ? 'selected' : ''}>${h(title)}</option>`).join('')}</select></label>`;
  return `<details class="catalog-filters"><summary>Find an available listing</summary><form id="catalog-form"><div class="filter-grid">${field('query', 'Player or card name', 'Name or certificate')}${select('category', 'Category', [['', 'All categories'], ['SPORTS', 'Sports'], ['POKEMON', 'Pokémon']])}${field('set', 'Set', 'Exact approved set')}${field('year', 'Year', '2026')}${field('grade', 'Grade', '9', 'decimal')}${field('minPriceCents', 'Minimum price (USD)', '0.00', 'decimal')}${field('maxPriceCents', 'Maximum price (USD)', '500.00', 'decimal')}${field('numberedDenominator', 'Numbered edition /', '99', 'numeric')}${select('autograph', 'Autograph', [['', 'Any / unknown included'], ['true', 'Recorded present'], ['false', 'Recorded absent']])}${select('relic', 'Relic', [['', 'Any / unknown included'], ['true', 'Recorded present'], ['false', 'Recorded absent']])}</div><div class="filter-actions"><button type="submit" class="button" ${blocked ? 'disabled' : ''}>Apply filters</button>${button('clear-filters', 'Clear filters', '', blocked, true)}</div></form></details>`;
}

function timestamp(value) {
  const time = typeof value === 'number' ? value : Date.parse(value);
  return Number.isFinite(time) ? new Date(time).toLocaleString('en-US') : 'Time unavailable';
}

function renderCheckout(listing, quote, reservation, payment, blocked, now, localDemo, data, ui) {
  if (reservation && reservation.status !== 'SOLD') {
    const attrs = identifier('reservation', reservation.id);
    const expired = Date.parse(reservation.expiresAt) <= now;
    const messages = {
      PREPARED: 'The original payment is saved but has not been dispatched. Resume it before the quote expires, or cancel this undispatched checkout.',
      VOIDED: 'This original payment was canceled locally before any dispatch. Refresh the retained checkout state.',
      DISPATCHING: 'The original payment request is in progress. Keep this card reserved until its exact result is known.',
      UNKNOWN: 'The provider result is unknown. The card remains held. Reconcile the original payment; refreshing never submits another charge.',
      PENDING: 'The original payment is pending. No sale is confirmed and the card remains held.',
      SUCCEEDED: 'Payment evidence is saved. Reconcile the original payment to complete the order.',
      CANCELED: 'Cancellation evidence is saved. Reconcile the original payment before releasing the card.',
      FAILED: 'A failed attempt does not prove the payment cannot complete. Reconcile the original payment before another checkout.',
    };
    return `<div class="purchase-review"><h3>${payment ? 'Payment recovery' : expired ? 'Reservation time elapsed' : 'Your card is reserved'}</h3><dl class="amounts">${amountRow('Total USD', reservation.quote?.totalCents ?? reservation.order?.totalCents, 'total')}</dl><p class="small">${h(payment ? messages[payment.status] ?? 'Payment status is unavailable. Reconcile the original intent.' : expired ? 'Payment cannot begin from an expired reservation. Refresh saved state to release an untouched hold, then review a new quote.' : `Held until ${timestamp(reservation.expiresAt)}. Begin payment before this deadline.`)}</p>${!payment ? `${button('pay', localDemo ? 'Begin synthetic payment' : 'Begin payment', attrs, blocked || expired)}${button('cancel-reservation', 'Cancel this unpaid reservation', attrs, blocked, true)}` : `${payment.status === 'PREPARED' ? button('pay', 'Resume original prepared payment', attrs, blocked || expired, true) : ''}${['PREPARED','VOIDED'].includes(payment.status) ? button('cancel-reservation', 'Cancel this undispatched checkout', attrs, blocked, true) : ''}${!localDemo && ['PENDING', 'UNKNOWN', 'DISPATCHING'].includes(payment.status) ? button('collect-payment', 'Enter payment details / complete authentication', attrs, blocked) : ''}${button('reconcile-payment', 'Reconcile original payment', attrs, blocked, true)}${localDemo && ['PENDING', 'UNKNOWN', 'DISPATCHING'].includes(payment.status) ? `<div class="simulation"><span class="eyebrow">LOCAL PROVIDER SIMULATOR</span>${button('simulate', 'Simulate payment confirmation', `${identifier('intent', payment.id)} data-status="succeeded"`, blocked, true)}${button('simulate', 'Simulate terminal unpaid cancellation', `${identifier('intent', payment.id)} data-status="canceled"`, blocked, true)}</div>` : ''}`}</div>`;
  }
  if (listing?.status !== 'ACTIVE') return '';
  const expired = quote && Date.parse(quote.expiresAt) <= now;
  const destinationRequired = data.quoteDestinationRequired === true;
  const destinations = Array.isArray(data.quoteDestinations) ? data.quoteDestinations : [];
  const selectedDestination = destinations.find(row => row.id === ui.destinationId);
  const destinationControl = destinationRequired ? `<label class="destination-picker">Delivery destination<select id="quote-destination" ${blocked ? 'disabled' : ''}><option value="">Choose a saved destination</option>${destinations.map(row => `<option value="${h(row.id)}" ${row.id === ui.destinationId ? 'selected' : ''}>${h(row.label)}</option>`).join('')}</select></label><p class="small">${destinations.length ? 'Changing destination requires a fresh shipping and tax quote.' : 'No qualified delivery destination is available. Checkout remains unavailable.'}</p>` : '';
  const quoteBlocked = blocked || destinationRequired && !selectedDestination;
  return `<div class="purchase-review"><h3>Your complete total</h3>${destinationControl}${quote ? `<dl class="amounts">${amountRow('Card', quote.itemCents)}${amountRow(quote.shippingCharge?.label??'Shipping', quote.shippingCents)}${amountRow('Tax', quote.taxCents)}${amountRow('Buyer premium', quote.buyerFeeCents)}${amountRow('Total USD', quote.totalCents, 'total')}</dl>${quote.shippingCharge?.disclosure?`<p class="small">${h(quote.shippingCharge.disclosure)}</p>`:''}<p class="small">${h(quote.deliveryEstimate)}</p>${quote.destination?.label ? `<p class="small">Destination: ${h(quote.destination.label)}</p>` : ''}<p class="small">${h(quote.protectionTerms)}</p><p class="small ${expired ? 'attention-text' : ''}">${expired ? 'This quote expired. Review a refreshed total before reserving.' : `Quote valid until ${h(timestamp(quote.expiresAt))}.`}</p>${button('reserve', 'Reserve this exact card', identifier('listing', listing.id), quoteBlocked || expired || destinationRequired && quote.destination?.id !== ui.destinationId)}${button('quote', 'Refresh complete buyer quote', identifier('listing', listing.id), quoteBlocked, true)}<p class="small muted">Reservation does not create a sale or transfer ownership.</p>` : `<p>Shipping, tax and protection terms are quoted before you reserve.</p>${button('quote', 'Review buyer total', identifier('listing', listing.id), quoteBlocked)}`}</div>`;
}

function renderSellerEligibility(value, localDemo) {
  const label = flag => flag === true ? (localDemo ? 'Eligible in local simulator' : 'Eligible at last observation') : flag === false ? 'Restricted' : 'Unverified';
  return `<div class="eligibility-panel"><div><h3>Connected account and bank eligibility</h3><p class="small">${h(value?.reason ?? (value?.status === 'ELIGIBLE' ? 'Current account and bank eligibility evidence is available. Fresh checks still apply before withdrawal.' : 'Current account evidence is unavailable or restricted. Withdrawal remains disabled.'))} ${value?.observedAt ? `Observed ${h(timestamp(value.observedAt))}.` : ''}</p></div><dl class="facts"><div><dt>Payments</dt><dd>${h(label(value?.chargesEnabled))}</dd></div><div><dt>Seller transfers</dt><dd>${h(label(value?.transfersEnabled))}</dd></div><div><dt>Bank payouts</dt><dd>${h(label(value?.payoutsEnabled))}</dd></div><div><dt>Bank verification</dt><dd>${h(value?.bank?.status ?? 'UNAVAILABLE')}${value?.bank?.label ? ` · ${h(value.bank.label)}` : ''}${/^\d{4}$/.test(value?.bank?.last4 ?? '') ? ` · ending ${h(value.bank.last4)}` : ''}</dd></div></dl>${value?.requirements?.length ? `<ul class="small">${value.requirements.map(item => `<li>${h(item)}</li>`).join('')}</ul>` : ''}<p class="small muted">Fresh account and bank evidence is checked again before dispatch. ${localDemo ? 'This local status does not qualify a real account.' : 'A previous observation does not guarantee a later dispatch.'}</p></div>`;
}

const dollars = value => Number.isSafeInteger(value) && value >= 0 ? `${Math.floor(value / 100)}.${String(value % 100).padStart(2, '0')}` : '';
function renderProtection(orders, fulfillment, intents, blocked, can, localDemo) {
  return `<section class="workflow-section" id="protection" aria-labelledby="protection-heading"><div class="section-heading"><p class="eyebrow">04 / CUSTOMER AND OPERATOR</p><h2 id="protection-heading">Protection and review</h2><p>Open a case, record an explicit review, and reconcile the original refund. Cases hold seller proceeds until reviewed resolution; a refund decision alone is not proof of returned money.</p></div>${orders.length ? orders.map(order => {
    const state = fulfillment[order.orderId], cases = state?.cases ?? [];
    return `<article class="protection-order"><h3>${h(order.approvedCard?.identity?.name ?? 'Synthetic order')}</h3><p class="small">${h(order.orderId)} · ${h(money(order.totalCents))} paid total</p>${can('BUYER') || can('SELLER') || can('STAFF') ? `<form data-form="case-open" ${identifier('order', order.orderId)} class="case-open"><label>Case reason<select name="kind"><option value="APPEAL">Appeal / ask for review</option><option value="DISPUTE">Dispute</option><option value="MISSING_SCAN">Missing tracking scan</option>${!order.returnPolicy||can('BUYER')?'<option value="RETURN">Request a return</option>':''}</select></label>${order.returnPolicy&&can('BUYER')?`<label>Return reason (for return requests)<select name="returnReason"><option value="">Choose a return reason</option><option value="SEVERE_DAMAGE">Severe damage</option><option value="WRONG_PRODUCT">Wrong product received</option></select></label><p class="small">Request within 24 hours of delivery and provide evidence for ATLAS staff review. ATLAS pays approved return shipping initially and determines final responsibility after review.${state?.releaseNotBefore?` Request deadline: ${h(timestamp(state.releaseNotBefore))}.`:''}</p>`:''}${localDemo ? '' : evidenceInput('evidenceRef', 'Existing case evidence reference', blocked)}<button class="button secondary" type="submit" ${blocked ? 'disabled' : ''}>${localDemo ? 'Open synthetic protection case' : 'Open protection case'}</button><p class="small">Missing scan and return requests must meet this order’s recorded policy and shipment milestones.</p></form>` : ''}${cases.length ? cases.map(item => renderCase(order, item, intents, blocked, can, localDemo)).join('') : '<p class="small muted">No protection cases recorded.</p>'}<details class="audit-trail"><summary>Recorded fulfillment milestones</summary>${state?.history?.length ? `<ol>${state.history.map(event => `<li>${h(event.action)} · ${h(timestamp(event.at))}</li>`).join('')}</ol>` : '<p class="small">Awaiting a recorded packing milestone.</p>'}</details></article>`;
  }).join('') : '<p class="empty-state">A reconciled paid order is required before a protection case can be opened.</p>'}</section>`;
}

function renderCase(order, item, intents, blocked, can, localDemo) {
  const obligation = item.refundObligation;
  const refund = intents.find(intent => intent.kind === 'REFUND' && intent.orderId === order.orderId && (intent.caseId === item.id || intent.policyEvidence?.caseId === item.id));
  const attrs = `${identifier('order', order.orderId)} ${identifier('case', item.id)}`;
  const open = item.status !== 'CLOSED';
  const pilotReturn=item.kind==='RETURN'&&order.returnPolicy?.requiresStaffReview===true;
  const needsReturnReview=pilotReturn&&item.returnReview?.decision!=='APPROVE';
  const returnReview=pilotReturn?`<p class="small">Return reason: ${h(item.returnReason==='SEVERE_DAMAGE'?'Severe damage':item.returnReason==='WRONG_PRODUCT'?'Wrong product':item.returnReason??'Unavailable')}. Staff decision: ${h(item.returnReview?.decision??'Awaiting review')}. ATLAS pays approved return shipping initially; final responsibility is reviewed separately.</p>${can('STAFF')&&item.evidenceRef?`<p class="small">Buyer evidence: ${h(item.evidenceRef)}</p>`:''}${open&&needsReturnReview&&can('STAFF')&&!localDemo?`<form data-form="return-review" ${attrs}><label>Evidence review<select name="decision"><option value="APPROVE">Approve return request</option><option value="DENY">Deny return request</option></select></label>${evidenceInput('reviewRef','Retained staff evidence review reference',blocked)}<p class="small">Approval keeps proceeds held and does not issue a refund. Denial closes this request; other holds and appeal rights remain.</p><button class="button secondary" type="submit" ${blocked?'disabled':''}>Record return review</button></form>`:''}`:'';
  const input = (name, label, amount) => `<label>${h(label)} (USD)<input name="${name}" inputmode="decimal" type="text" value="${dollars(amount)}" required ${blocked ? 'disabled' : ''}></label>`;
  return `<div class="case-panel"><div class="case-heading"><div><p class="eyebrow">${h(item.kind)} / ${h(item.id)}</p><h4>${h(open ? 'Review required · proceeds held' : `Closed · ${item.outcome}`)}</h4></div><span class="status-pill">${h(item.status)}</span></div><p class="small">Opened ${h(timestamp(item.openedAt))}. ${open ? 'Physical and money actions remain subject to this case.' : 'The recorded resolution remains available for review.'}</p>${returnReview}${obligation ? `<dl class="amounts">${amountRow('Reviewed refund total', obligation.amountCents, 'total')}${amountRow('Seller allocation', obligation.allocations.sellerCents)}${amountRow('Fee allocation', obligation.allocations.feeCents)}${amountRow('Tax allocation', obligation.allocations.taxCents)}${amountRow('Shipping allocation', obligation.allocations.shippingCents)}</dl><p class="small">Policy ${h(obligation.policyVersion)} · Refund: <strong>${h(refund?.status ?? 'Awaiting retained intent')}</strong>. Reviewed amounts cannot be changed on retry.</p>` : ''}${open && can('STAFF') && !needsReturnReview ? `<div class="operator-controls"><p class="eyebrow">${localDemo ? 'EXPLICIT LOCAL OPERATOR CONTROLS' : 'AUTHENTICATED OPERATOR REVIEW'}</p>${!obligation ? `<details><summary>Review a full or partial refund</summary><form data-form="refund-review" ${attrs}><div class="review-grid">${input('sellerCents', 'Seller proceeds', order.sellerNetCents)}${input('feeCents', 'Marketplace fee', order.feeCents)}${input('taxCents', 'Tax', order.taxCents)}${input('shippingCents', 'Shipping', order.shippingCents)}</div><label class="check-label"><input type="checkbox" name="reviewConfirmed" required> I reviewed this exact ${localDemo ? 'synthetic ' : ''}case, the allocation and the purchased policy.</label><p class="small">The refund total is the exact sum above. Submission freezes this obligation and starts its original refund intent; it does not close the case.</p>${localDemo ? '' : evidenceInput('reviewRef', 'Existing reviewed decision reference', blocked)}<button class="button" type="submit" ${blocked ? 'disabled' : ''}>${localDemo ? 'Record review and begin synthetic refund' : 'Record review and begin refund'}</button></form></details>` : `${!refund || refund.status === 'PREPARED' ? button('resume-refund', 'Resume original reviewed refund', attrs, blocked, true) : ''}${button('reconcile-refund', 'Reconcile original case refund', attrs, blocked, true)}${localDemo && refund && ['PENDING', 'UNKNOWN', 'DISPATCHING'].includes(refund.status) ? button('simulate', 'Simulate original refund confirmation', `${identifier('intent', refund.id)} data-status="succeeded"`, blocked, true) : ''}`}
    <form data-form="case-resolve" ${attrs} ${identifier('refund', refund?.id ?? '')}><label>Reviewed outcome<select name="outcome">${obligation ? '<option value="REFUND_REQUIRED">Close after exact confirmed refund</option>' : '<option value="NO_REFUND_DUE">Reviewed: no refund due</option><option value="APPEAL_UPHELD">Appeal upheld, no refund obligation</option><option value="APPEAL_REJECTED">Appeal rejected</option>'}</select></label>${localDemo ? item.kind === 'RETURN' ? '<label class="check-label"><input type="checkbox" name="inspectionConfirmed" required> I recorded the returned parcel, Front, Back and holder inspection in this synthetic review.</label>' : '' : `${evidenceInput('ref', 'Reviewed resolution reference', blocked)}${item.kind === 'RETURN' ? ['receivedParcelRef', 'inspectionFrontRef', 'inspectionBackRef', 'holderInspectionRef'].map(key => evidenceInput(key, evidenceLabels[key], blocked)).join('') : ''}`}<button class="button secondary" type="submit" ${blocked || (obligation && (refund?.status !== 'SUCCEEDED' || refund?.confirmed !== true)) ? 'disabled' : ''}>Record reviewed resolution</button></form></div>` : ''}${item.history?.length ? `<details class="audit-trail"><summary>Resolution history</summary><ol>${item.history.map(event => `<li>Review recorded · ${h(timestamp(event.at))}</li>`).join('')}</ol></details>` : ''}</div>`;
}

const evidenceLabels = {
  ref: 'Evidence record reference', intakeFrontRef: 'Intake Front photograph reference', intakeBackRef: 'Intake Back photograph reference',
  holderConditionRef: 'Holder condition reference', packingPhotoRef: 'Packing photograph reference', fittedInsertRef: 'Fitted insert evidence reference',
  firstSealRef: 'First seal evidence reference', secondSealRef: 'Second seal evidence reference', cleanLabelAreaRef: 'Clean label area evidence reference',
  resaleInstructionsRef: 'Resale instructions reference', replacementKitRef: 'Replacement kit reference', carrierRef: 'Carrier reference',
  trackingRef: 'Tracking reference', coverageRef: 'Coverage reference', dispatchReceiptRef: 'Dispatch receipt reference', deliveryProofRef: 'Delivery proof reference',
  releaseReviewRef: 'Release review reference', receivedParcelRef: 'Returned parcel receipt reference', inspectionFrontRef: 'Returned Front inspection reference',
  inspectionBackRef: 'Returned Back inspection reference', holderInspectionRef: 'Returned holder inspection reference',
};
const evidenceInput = (name, label, blocked) => `<label class="evidence-field">${h(label)}<input type="text" name="${h(name)}" autocomplete="off" maxlength="128" required ${blocked ? 'disabled' : ''}></label>`;
function renderFulfillmentForm(order, action, blocked) {
  const fields = { PACK: ['intakeFrontRef', 'intakeBackRef', 'holderConditionRef', 'packingPhotoRef', 'fittedInsertRef', 'firstSealRef', 'secondSealRef', 'cleanLabelAreaRef', 'resaleInstructionsRef', 'replacementKitRef'], DISPATCH: ['carrierRef', 'trackingRef', 'coverageRef', 'dispatchReceiptRef'], DELIVER: ['deliveryProofRef'], RELEASE: ['releaseReviewRef'] }[action];
  return `<details class="operator-controls"><summary>Record ${h(action.toLowerCase())} evidence</summary><form data-form="fulfillment-evidence" ${identifier('order', order.orderId)} ${identifier('step', action)}><p class="small">Use retained references from actual work. This form creates no photographs, shipment, coverage or inspection evidence.</p>${['ref', ...fields].map(key => evidenceInput(key, evidenceLabels[key], blocked)).join('')}${action==='DELIVER'?`<label>Carrier delivery date and time (your local time)<input type="datetime-local" name="deliveredAt" step="1" required ${blocked?'disabled':''}></label>`:''}<button class="button secondary" type="submit" ${blocked ? 'disabled' : ''}>Record verified ${h(action.toLowerCase())} milestone</button></form></details>`;
}

function renderSeller({ card, firstName, selected, editable, activeCommerce, consent, policy, blocked, ui, localDemo, feePreviewRequired, now }) {
  const price = ui.price ?? (localDemo ? '125.00' : '');
  const consentBlocked = blocked || !card || Boolean(activeCommerce);
  const feeQuote = card && ui.feeQuote && ui.feeQuote.cardId === card.cardId && ui.feeQuote.askingPriceCents === parsePrice(price) && Date.parse(ui.feeQuote.expiresAt) > now && (editable ? ui.feeQuote.listingId === selected.id && ui.feeQuote.listingVersion === selected.version && ui.feeQuote.listingHash === selected.bindingHash : ui.feeQuote.listingId === null) ? ui.feeQuote : null;
  const fee = feePreviewRequired ? feeQuote?.feeCents : policy?.feeCents;
  const net = feePreviewRequired ? feeQuote?.sellerNetCents : sellerNet(price, fee);
  return `<section class="workflow-section" id="sell" aria-labelledby="sell-heading"><div class="section-heading"><p class="eyebrow">01 / SELLER</p><h2 id="sell-heading">Choose what happens next.</h2><p>Ship to me and Hold and list are separate recorded choices. Listing requires current title, consignment, ATLAS custody and eligible seller evidence.</p></div><div class="seller-grid"><div class="panel"><h3>Card disposition</h3><p>${h(firstName)}</p>${localDemo ? `<div class="stack">${button('consent', 'Hold and list · synthetic consent', `${identifier('card', card?.cardId ?? '')} data-choice="HOLD_AND_LIST"`, consentBlocked, consent?.choice !== 'HOLD_AND_LIST')}${button('consent', 'Ship to me · synthetic choice', `${identifier('card', card?.cardId ?? '')} data-choice="SHIP_TO_ME"`, consentBlocked, true)}</div>` : `<form data-form="consent" ${identifier('card', card?.cardId ?? '')}><label>Disposition choice<select name="choice" ${consentBlocked ? 'disabled' : ''}><option value="HOLD_AND_LIST">Hold and list</option><option value="SHIP_TO_ME">Ship to me</option></select></label>${evidenceInput('evidenceRef', 'Recorded consignment / disposition reference', consentBlocked)}<button class="button secondary" type="submit" ${consentBlocked ? 'disabled' : ''}>Record my explicit choice</button></form>`}<p class="small">Recorded choice: <strong>${h(consent?.choice === 'HOLD_AND_LIST' ? 'Hold and list' : consent?.choice === 'SHIP_TO_ME' ? 'Ship to me' : 'None yet')}</strong>. ${localDemo ? 'No physical shipment is requested in this demo.' : 'Disposition alone does not establish title, custody or listing eligibility.'}</p></div>
    <form class="panel" id="listing-form" data-mode="${editable ? 'revise' : 'create'}" ${identifier('listing', selected?.id ?? '')}><h3>${editable ? 'Revise your asking price' : 'Review your listing'}</h3><label for="asking-price">Your asking price (USD)</label><div class="price-input"><span aria-hidden="true">$</span><input id="asking-price" name="askingPrice" type="text" inputmode="decimal" autocomplete="off" value="${h(price)}" required ${blocked || Boolean(activeCommerce && !editable) ? 'disabled' : ''}></div><dl class="amounts seller-amounts">${amountRow('Marketplace fee', fee)}${amountRow('You receive', net, 'total')}</dl><p class="small" id="fee-disclosure">${h(feeQuote?.feeDisclosure ?? policy?.feeDisclosure ?? 'Fee policy unavailable. Listing is disabled.')}</p>${feePreviewRequired ? `${button('preview-fee', 'Review exact fee and proceeds', '', blocked || !card || Boolean(activeCommerce && !editable), true)}<p class="small">${feeQuote ? `Reviewed fee valid until ${h(timestamp(feeQuote.expiresAt))}.` : 'Review a current fee quote for this exact price before listing.'}</p>` : ''}<button class="button" type="submit" aria-describedby="fee-disclosure" ${blocked || !card || Boolean(activeCommerce && !editable) || !policy || feePreviewRequired && !feeQuote || consent?.choice !== 'HOLD_AND_LIST' ? 'disabled' : ''}>${editable ? 'Save new listing revision' : activeCommerce ? 'Listing recorded' : localDemo ? 'List for sale · synthetic' : 'List for sale'}</button><p class="small muted">Your asking price is explicit. Saved report values remain unchanged. A revision invalidates earlier buyer quotes.</p>${editable ? button('withdraw-listing', 'Withdraw available listing', identifier('listing', selected.id), blocked, true) : ''}</form></div></section>`;
}


function renderInstantWithdrawal(balance, eligibility, ui, blocked, now) {
  const bankId = eligibility.bank?.externalAccountId;
  const quote = ui.instantQuote?.externalAccountId === bankId && ui.instantQuote.amountCents === parsePrice(ui.instantAmount ?? '') ? ui.instantQuote : null;
  const valid = quote && quote.method === 'instant' && Date.parse(quote.expiresAt) > now && Number.isSafeInteger(quote.totalDebitCents) && quote.totalDebitCents <= balance?.availableCents;
  return `<div class="panel instant-withdrawal"><h3>Optional instant payout</h3><p class="small">Availability, fee and timing require a current quote for this exact bank and amount.</p><label>Amount to your bank (USD)<input id="instant-amount" inputmode="decimal" autocomplete="off" value="${h(ui.instantAmount ?? '')}" ${blocked ? 'disabled' : ''}></label>${button('quote-withdrawal', 'Review instant payout fee', identifier('bank', bankId ?? ''), blocked || !bankId, true)}${quote ? `<div class="instant-review"><dl class="amounts">${amountRow('To your bank', quote.amountCents)}${amountRow('Instant payout fee', quote.sellerFeeCents)}${amountRow('Total balance debit', quote.totalDebitCents, 'total')}</dl><p class="small">${h(quote.feeDisclosure)}</p><p class="small">${h(quote.timingDisclosure)}</p><p class="small">${valid ? `Quote valid until ${h(timestamp(quote.expiresAt))}.` : 'This quote expired or its total exceeds your available balance. Request a new quote.'}</p>${button('confirm-instant-withdrawal', 'Confirm this instant payout and fee', identifier('quote', quote.quoteId), blocked || !valid)}</div>` : '<p class="small">No instant payout is submitted until you review and confirm a complete quote.</p>'}</div>`;
}

function renderTaxReporting(reporting, blocked) {
  const unavailable = reporting?.available !== true, disabled = blocked || unavailable;
  const orders = Array.isArray(reporting?.orders) ? reporting.orders : [];
  const recovery = (status, operationId) => {
    if (!operationId || !['PREPARED', 'DISPATCHING', 'UNKNOWN'].includes(status)) return '';
    if (status === 'PREPARED') return `<form data-form="tax-resume" ${identifier('operation', operationId)}><p class="small">This retained record has not been dispatched. Resume preserves its approved original amounts and review.</p><button class="button secondary" type="submit" ${disabled ? 'disabled' : ''}>Resume approved tax record</button></form>`;
    return `<form data-form="tax-reconcile" ${identifier('operation', operationId)}><p class="small">Reconciliation retrieves the original tax record. It never repeats a tax write. If its provider ID was lost, independently verify that exact original ID and retain a review reference.</p><label>Original provider tax ID (optional)<input name="providerId" maxlength="128" autocomplete="off" spellcheck="false" ${disabled ? 'disabled' : ''}></label><label>Independent recovery review reference (required with an ID)<input name="reviewRef" maxlength="500" autocomplete="off" ${disabled ? 'disabled' : ''}></label><button class="button secondary" type="submit" ${disabled ? 'disabled' : ''}>Reconcile original tax record</button></form>`;
  };
  return `<section class="workflow-section" id="tax-reporting"><div class="section-heading"><p class="eyebrow">STAFF / TAX REPORTING</p><h2>Record paid sale and refund tax</h2><p>These orders are already paid. Tax reporting review does not change payment confirmation. Required tax records can hold fulfillment or case closure until reconciled.</p></div>${unavailable ? '<p class="empty-state">The approved tax reporting service is unavailable. Existing obligations remain recorded.</p>' : ''}${orders.map(order => `<article class="panel"><h3>Paid order ${h(order.orderId)}</h3><p>Sale tax record: <strong>${h(order.saleStatus)}</strong></p>${order.saleStatus === 'MISSING' ? `<form data-form="tax-sale" ${identifier('order', order.orderId)}><p class="small">Record the exact retained checkout calculation against this confirmed payment.</p><button class="button secondary" type="submit" ${disabled ? 'disabled' : ''}>Record original sale tax</button></form>` : recovery(order.saleStatus, order.operationId)}${(Array.isArray(order.refunds) ? order.refunds : []).map(refund => `<div class="case-panel"><h4>Confirmed refund ${h(refund.refundIntentId)}</h4><p>Refunded tax: ${h(money(refund.taxCents))} · Tax reversal: <strong>${h(refund.status)}</strong></p>${refund.status === 'MISSING' ? `<form data-form="tax-refund" ${identifier('refund', refund.refundIntentId)}><p class="small">Review the item and shipping tax split from the original calculation. Enter integer cents totaling exactly ${h(refund.taxCents)}; no proportional allocation is assumed.</p><div class="review-grid">${[['itemTaxCents','Item tax (integer cents)'],['shippingTaxCents','Shipping tax (integer cents)']].map(([name,label]) => `<label>${label}<input name="${name}" type="number" inputmode="numeric" min="0" max="${h(refund.taxCents)}" step="1" required ${disabled || order.saleStatus !== 'SUCCEEDED' ? 'disabled' : ''}></label>`).join('')}</div>${evidenceInput('reviewRef', 'Retained exact tax allocation review reference', disabled || order.saleStatus !== 'SUCCEEDED')}<label class="check-label"><input type="checkbox" name="reviewConfirmed" required ${disabled || order.saleStatus !== 'SUCCEEDED' ? 'disabled' : ''}> I reviewed this exact confirmed refund and its tax allocation.</label><button class="button secondary" type="submit" ${disabled || order.saleStatus !== 'SUCCEEDED' ? 'disabled' : ''}>Record reviewed tax reversal</button>${order.saleStatus !== 'SUCCEEDED' ? '<p class="small">Reconcile the original sale tax record first.</p>' : ''}</form>` : recovery(refund.status, refund.operationId)}</div>`).join('')}</article>`).join('') || (unavailable ? '' : '<p class="empty-state">No retained paid-order tax obligations.</p>')}</section>`;
}

function renderFinanceIncidents(operations, blocked) {
  const incidents = Array.isArray(operations?.incidents) ? operations.incidents : [];
  return `<section class="workflow-section" id="finance-operations"><div class="section-heading"><p class="eyebrow">STAFF / FINANCE OPERATIONS</p><h2>Reconciliation incidents</h2><p>Review current evidence explicitly. Resolving an alert does not clear a money exception, release funds or dispatch a payment.</p></div>${renderInstantFeeSettlement(operations, blocked)}${operations ? `<p class="small">Open: ${h(operations.incidentCounts?.open ?? 0)} · Acknowledged: ${h(operations.incidentCounts?.acknowledged ?? 0)} · Resolved: ${h(operations.incidentCounts?.resolved ?? 0)}</p>` : '<p class="empty-state">Operational evidence is unavailable.</p>'}${incidents.map(item => `<article class="panel finance-incident"><p class="eyebrow">${h(item.code)} / ${h(item.alertId)}</p><h3>${h(item.status)}</h3><p class="small">Reference ${h(item.reference)} · Generation ${h(item.generation)} · Version ${h(item.version)}</p><p class="small">First observed ${h(timestamp(item.firstObservedAt))}; latest ${h(timestamp(item.lastObservedAt))}. Alert delivery: ${h(item.deliveryStatus ?? 'Unavailable')}.</p>${item.status !== 'RESOLVED' ? `<form data-form="finance-incident" ${identifier('alert', item.alertId)}><label>Review action<select name="action" ${blocked ? 'disabled' : ''}><option value="ACKNOWLEDGE">Acknowledge current incident</option><option value="RESOLVE">Resolve this reviewed alert</option></select></label>${evidenceInput('reviewRef', 'Retained review evidence reference', blocked)}<label class="check-label"><input name="reviewConfirmed" type="checkbox" required ${blocked ? 'disabled' : ''}> I reviewed this version and its current evidence.</label><button class="button secondary" type="submit" ${blocked || !item.latestEvidenceHash ? 'disabled' : ''}>Record incident review</button></form>` : '<p class="small">Resolved review retained. A recurrence is a new incident generation.</p>'}</article>`).join('') || (operations ? '<p class="empty-state">No retained reconciliation incidents.</p>' : '')}</section>`;
}


function renderInstantFeeSettlement(operations, blocked) {
  if (operations?.instantFeeSettlementAvailable !== true) return '';
  const intents = Array.isArray(operations.unsettledInstantFeeIntents) ? operations.unsettledInstantFeeIntents : [];
  return `<div class="panel instant-fee-settlement"><h3>Reconcile provider instant payout fees</h3><p class="small">Use the genuine provider fee assessment and retained review. This records the exact assessed fee allocation; it does not initiate another payout.</p>${intents.length ? `<form data-form="instant-fee-settlement"><fieldset><legend>Exact payout intents covered by this assessment</legend>${intents.map(item => `<label class="check-label"><input type="checkbox" name="intentIds" value="${h(item.id)}" ${blocked ? 'disabled' : ''}><span>${h(item.id)} · Bank amount ${h(money(item.amountCents))} · Expected provider fee ${h(money(item.providerFeeCents))}</span></label>`).join('')}</fieldset>${evidenceInput('evidenceRef', 'Retained provider assessment reference', blocked)}${evidenceInput('reviewRef', 'Retained fee allocation review reference', blocked)}<label class="check-label"><input type="checkbox" name="reviewConfirmed" required ${blocked ? 'disabled' : ''}> I reviewed these exact intents and their provider fee evidence.</label><button class="button secondary" type="submit" ${blocked ? 'disabled' : ''}>Record reviewed fee settlement</button></form>` : '<p class="small">No eligible unsettled instant payout fees.</p>'}</div>`;
}
